fn fibonacci(n: usize) -> Vec<i32> {
    // Given n >= 2, we start with the first two Fibonacci numbers:
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    // Compute Fibonacci numbers from index 2 up to n-1.
    for i in 2..n {
        // Safe to unwrap because fibs has at least i and i-1 elements here.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}